const e=[{title:"What is MLOps?",subtitle:"From Notebook to Owned Service",bullets:["MLOps applies DevOps discipline to data, models, and experiments.","Goal: reproducible training, safe deployment, and continuous monitoring.","Bridges data science, engineering, and operations teams."],speakerNote:"Ask who has had a model 'work in Jupyter' but fail in production."},{title:"ML System Components",bullets:["Data pipelines — ingestion, validation, feature stores.","Training pipelines — experiment tracking, model registry.","Serving — APIs, batch scoring, edge deployment.","Monitoring — data drift, concept drift, performance decay."],speakerNote:"Map components to tools trainees may already know (Git, Docker, cloud)."},{title:"Reproducibility",table:{headers:["Artifact","Why version it"],rows:[["Code + config","Recreate training exactly"],["Training data snapshot","Audit and debug drift"],["Model weights","Rollback and compare"],["Environment","Same dependencies in train and serve"]]},speakerNote:"Without data versioning, you cannot explain last month's metric drop."},{title:"Experiment Tracking",bullets:["Log parameters, metrics, artifacts, and git SHA per run.","Compare runs side-by-side before promoting a model.","Tools: MLflow, Weights & Biases, Neptune, cloud-native trackers."],speakerNote:"Show one MLflow UI screenshot if available."},{title:"Model Registry & Promotion",bullets:["Stages: staging → production → archived.","Promotion gates: metric thresholds, bias checks, sign-off.","Never deploy straight from a laptop without registry metadata."],speakerNote:"Tie registry to change management in enterprise IT."},{title:"CI/CD for Machine Learning",bullets:["CI: unit tests + data/schema validation + training smoke tests.","CD: deploy container or endpoint when registry stage changes.","Feature pipelines may need separate release cadence from models."],speakerNote:"Contrast app CI (code only) vs ML CI (data + model)."},{title:"Data Drift vs Concept Drift",table:{headers:["Type","Definition","Example signal"],rows:[["Data drift","Input distribution changes","New user demographics"],["Concept drift","P(y|x) changes","Fraud patterns evolve"],["Label drift","Labeling policy changes","Stricter QA on positives"]]},speakerNote:"Monitoring without action is useless — define playbooks per drift type."},{title:"Monitoring in Production",bullets:["Track latency, error rate, throughput at the serving layer.","Track prediction distribution and feature statistics over time.","Alert on SLA breaches and statistical tests vs training baseline."],speakerNote:"Golden rule: monitor what you would check the morning after launch."},{title:"Feature Stores",body:"Centralize features for training and serving to prevent train-serve skew.",bullets:["Same feature definitions online and offline.","Point-in-time correctness for historical training sets.","Reuse across teams — reduces duplicated ETL."],speakerNote:"Train-serve skew is a top cause of silent production degradation."},{title:"Deployment Patterns",bullets:["Batch scoring for reports and nightly jobs.","Real-time REST/gRPC for interactive products.","Shadow / canary deploys to compare new model safely."],speakerNote:"Canary: route 5% traffic, compare business metrics before full cutover."},{title:"Mini Lab — MLflow-style Run Log",type:"code",language:"python",code:`# Minimal experiment log pattern (conceptual)
run = {
    "params": {"lr": 0.01, "max_depth": 5},
    "metrics": {"f1": 0.82, "latency_ms": 45},
    "tags": {"git_sha": "abc123", "data_version": "2026-06-01"},
}
print("Registered run:", run)
# In production: push to MLflow / W&B / cloud tracker`,speakerNote:"Emphasize tags for audit — who trained, on what data, when."},{title:"Capstone — Your MLOps Roadmap",bullets:["Pick one model from the bootcamp and draw its production path.","List 3 metrics you would monitor week one after launch.","Identify the single biggest reproducibility gap in your current workflow."],speakerNote:"Close bootcamp — collect roadmaps as exit ticket; celebrate completion."}];export{e as slides};
